<?php if(!$product):?><section class="section"><div class="container"><h1>Product not found</h1></div></section><?php else:?><section class="page-hero"><div class="container narrow"><p class="eyebrow">Product</p><h1><?=e($product['name'])?></h1><p><?=e($product['summary'])?></p></div></section><section class="section"><div class="container detail-grid"><div><h2>About this product</h2><p><?=e($product['description'])?></p></div><aside class="panel"><p class="price"><?=e(money((int)$product['price_pence'],$store))?></p><p class="muted"><?=e((string)$product['stock'])?> in stock</p><form class="form-grid" method="post" action="/cart"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="slug" value="<?=e($product['slug'])?>"><div class="field"><label for="quantity">Quantity</label><input class="quantity-input" id="quantity" name="quantity" type="number" min="1" max="<?=e((string)$product['stock'])?>" value="1"></div><button class="button primary" type="submit">Add to basket</button></form></aside></div></section><?php endif;?>
